targets.expr:
sum by (system) (
  gbfs_station_vehicles_available{job=~"$job", system=~"$system"}
    and on (system, station_id) gbfs_station_capacity{job=~"$job", system=~"$system"}
)
/
sum by (system) (
  gbfs_station_capacity{job=~"$job", system=~"$system"}
    and on (system, station_id) gbfs_station_vehicles_available{job=~"$job", system=~"$system"}
)

count by (system) (
  gbfs_station_vehicles_available{job=~"$job", system=~"$system"}
    + on (system, station_id) gbfs_station_docks_available{job=~"$job", system=~"$system"}
    > on (system, station_id) gbfs_station_capacity{job=~"$job", system=~"$system"}
)
or (sum by (system) (gbfs_up{job=~"$job", system=~"$system"}) * 0)
